function addForwardLists(a: ListNode | null, b: ListNode | null): ListNode | null {
  const reverse = (h: ListNode | null): ListNode | null => {
    let prev: ListNode | null = null;
    while (h) { const nx = h.next; h.next = prev; prev = h; h = nx; }
    return prev;
  };
  let x = reverse(a), y = reverse(b), carry = 0;
  const dummy = new ListNode(0);
  let tail = dummy;
  while (x || y || carry) {
    const sum = (x ? x.val : 0) + (y ? y.val : 0) + carry;
    carry = Math.floor(sum / 10);
    tail.next = new ListNode(sum % 10);
    tail = tail.next;
    if (x) x = x.next;
    if (y) y = y.next;
  }
  return reverse(dummy.next);
}

