class Solution:
    def addForwardLists(self, a: Optional[ListNode], b: Optional[ListNode]) -> Optional[ListNode]:
        def reverse(h):
            prev = None
            while h:
                h.next, prev, h = prev, h, h.next
            return prev

        x, y, carry = reverse(a), reverse(b), 0
        dummy = tail = ListNode(0)
        while x or y or carry:
            s = (x.val if x else 0) + (y.val if y else 0) + carry
            carry, d = divmod(s, 10)
            tail.next = ListNode(d)
            tail = tail.next
            x = x.next if x else None
            y = y.next if y else None
        return reverse(dummy.next)

