function addForwardLists(a: ListNode | null, b: ListNode | null): ListNode | null {
  const sa: number[] = [], sb: number[] = [];
  for (let p = a; p; p = p.next) sa.push(p.val);
  for (let p = b; p; p = p.next) sb.push(p.val);
  let carry = 0;
  let head: ListNode | null = null;
  while (sa.length || sb.length || carry) {
    const sum = (sa.pop() ?? 0) + (sb.pop() ?? 0) + carry;
    carry = Math.floor(sum / 10);
    head = new ListNode(sum % 10, head);
  }
  return head;
}

